// ALGORITHMIQUE & PROGRAMMATION (INFO101B) — CRÉDITS : 3
// TP : Implémentation comparée des algorithmes de tri (Bulle, Insertion, Tri Rapide)
#include <stdio.h>
#include <stdlib.h>

void echanger(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Tri à bulles optimisé
void triABulles(int tab[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int permute = 0;
        for (int j = 0; j < n - i - 1; j++) {
            if (tab[j] > tab[j + 1]) {
                echanger(&tab[j], &tab[j + 1]);
                permute = 1;
            }
        }
        if (!permute) break;
    }
}

// Partition pour le tri rapide (Quicksort)
int partition(int tab[], int bas, int haut) {
    int pivot = tab[haut];
    int i = (bas - 1);
    for (int j = bas; j < haut; j++) {
        if (tab[j] < pivot) {
            i++;
            echanger(&tab[i], &tab[j]);
        }
    }
    echanger(&tab[i + 1], &tab[haut]);
    return (i + 1);
}

void triRapide(int tab[], int bas, int haut) {
    if (bas < haut) {
        int pi = partition(tab, bas, haut);
        triRapide(tab, bas, pi - 1);
        triRapide(tab, pi + 1, haut);
    }
}

int main() {
    int donnees[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(donnees) / sizeof(donnees[0]);
    triRapide(donnees, 0, n - 1);
    printf("Tableau trie avec succes : ");
    for (int i = 0; i < n; i++) printf("%d ", donnees[i]);
    printf("\n");
    return 0;
}

# ALGORITHMIQUE & STRUCTURES DE DONNÉES (INFO101B)
# TP : Algorithme de Dijkstra avec file de priorité (heapq)
import heapq

def dijkstra(graphe, depart):
    distances = {noeud: float('infinity') for noeud in graphe}
    distances[depart] = 0
    precedents = {noeud: None for noeud in graphe}
    file_prio = [(0, depart)]

    while file_prio:
        dist_actuelle, noeud_actuel = heapq.heappop(file_prio)

        if dist_actuelle > distances[noeud_actuel]:
            continue

        for voisin, poids in graphe[noeud_actuel].items():
            distance = dist_actuelle + poids
            if distance < distances[voisin]:
                distances[voisin] = distance
                precedents[voisin] = noeud_actuel
                heapq.heappush(file_prio, (distance, voisin))

    return distances, precedents

